const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '比例尺 1:50000（示意图）' },
      { kind: 'text', payload: '图上距离 4 厘米' },
      { kind: 'text', payload: '实际距离 200000 厘米' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: '厘米' }
    ];
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 480;
    var H = (input.viewport && input.viewport.heightDu) || 260;
    function tw(i, fb) {
      var m = metrics && metrics[i];
      if (m && typeof m.width === 'number' && m.width > 0) { return m.width; }
      return fb;
    }
    var ink = '#26354a';
    var pad = Math.max(56, W * 0.14);
    var x0 = pad;
    var x1 = W - pad;
    var yR = H * 0.58;
    var yArrow = H * 0.36;
    var majorLen = Math.max(9, H * 0.05);
    var minorLen = majorLen * 0.55;

    var ruler = visualSdk.polyline([[x0, yR], [x1, yR]]);
    var ticks = [];
    var i, x, len, major;
    for (i = 0; i <= 8; i++) {
      x = x0 + (x1 - x0) * i / 8;
      major = (i % 2 === 0);
      len = major ? majorLen : minorLen;
      ticks = ticks.concat(visualSdk.polyline([[x, yR - len], [x, yR + len]]));
    }
    var ext = [];
    ext = ext.concat(visualSdk.polyline([[x0, yR - majorLen - 4], [x0, yArrow]]));
    ext = ext.concat(visualSdk.polyline([[x1, yR - majorLen - 4], [x1, yArrow]]));
    var arrow = visualSdk.polyline([[x0, yArrow], [x1, yArrow]]);
    var ah = Math.max(9, H * 0.045);
    var aw = ah * 0.55;
    var heads = [];
    heads = heads.concat(visualSdk.polyline([[x0 + ah, yArrow - aw], [x0, yArrow], [x0 + ah, yArrow + aw]]));
    heads = heads.concat(visualSdk.polyline([[x1 - ah, yArrow - aw], [x1, yArrow], [x1 - ah, yArrow + aw]]));

    var labels = [];
    labels.push({
      type: 'label', text: '比例尺 1:50000（示意图）',
      x: W / 2, y: H * 0.11, fontSize: 15, fill: ink, align: 'center'
    });
    labels.push({
      type: 'label', text: '图上距离 4 厘米',
      x: W / 2, y: yArrow - Math.max(14, H * 0.055), fontSize: 13, fill: ink, align: 'center'
    });
    var numY = yR + majorLen + Math.max(14, H * 0.055);
    var names = ['0', '1', '2', '3', '4'];
    for (i = 0; i <= 4; i++) {
      x = x0 + (x1 - x0) * i / 4;
      labels.push({
        type: 'label', text: names[i],
        x: x, y: numY, fontSize: 12, fill: ink, align: 'center'
      });
    }
    var unitW = tw(8, 26);
    labels.push({
      type: 'label', text: '厘米',
      x: x1 + tw(7, 8) / 2 + 6 + unitW / 2,
      y: numY, fontSize: 12, fill: ink, align: 'center'
    });
    labels.push({
      type: 'label', text: '实际距离 200000 厘米',
      x: W / 2, y: yR + H * 0.30, fontSize: 14, fill: ink, align: 'center'
    });

    var children = [
      { type: 'path', pathId: 'ext', stroke: ink, strokeWidth: 1, fill: 'none' },
      { type: 'path', pathId: 'arrow', stroke: ink, strokeWidth: 1.4, fill: 'none' },
      { type: 'path', pathId: 'heads', stroke: ink, strokeWidth: 1.4, fill: 'none' },
      { type: 'path', pathId: 'ruler', stroke: ink, strokeWidth: 2.2, fill: 'none' },
      { type: 'path', pathId: 'ticks', stroke: ink, strokeWidth: 1.2, fill: 'none' }
    ].concat(labels);

    return {
      schemaVersion: 1,
      sceneId: 'fig-scale-1-50000',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ruler', commands: ruler },
        { id: 'ticks', commands: ticks },
        { id: 'ext', commands: ext },
        { id: 'arrow', commands: arrow },
        { id: 'heads', commands: heads }
      ],
      root: { type: 'group', children: children }
    };
  }
};
